script.inlineScript:
/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 * @param {any} params.imports
 */
function evaluateEvent({
    api,
    event
}) {
    let basic = api.state.pluginSetupType.basic;
    let recommended = api.state.pluginSetupType.recommended;
    let plugins = api.state.plugins.map(plugin => {
        return { ...plugin,
            isQSChecked: basic.includes(plugin.sys_id),
            isBEChecked: basic.includes(plugin.sys_id) || recommended.includes(plugin.sys_id),
            isBEDisabled: basic.includes(plugin.sys_id)
        };
    });
    return {
        propName: 'plugins',
        value: plugins
    };
}

/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 * @param {any} params.imports
 */
function evaluateEvent({
    api,
    event
}) {
    return {
    	propName: 'plugins',
    	value: event.payload
    };
}
